//! Vectors for the plans of the three files a verifier reads, generated by
//! `scripts/cpp_vectors/frame_files_vectors.cpp`:
//! `Subproofs`/`stand_in_subproofs`, `frame_shape_of`, `sized`, `file_proof`, `file_key`,
//! `file_entry`, `merged` (`blocks/frame/files.h`) and `KeyFixed`/`key_fixed`/
//! `key_public_bytes`/`key_fault` (`blocks/frame/key_fixed.h`).
//!
//! The first half runs the accepted `fixtures/config/policy.txt` through the stand-in; that
//! policy's table is too small for the stand-in's matrix, so `sized` refuses and every file is a
//! set of rejected chains, with the exact reason. The second half runs the same flow on
//! `fixtures/config-standin/policy.txt` (the C++ `blocks/frame/examples/record.f2.txt`), whose
//! table the stand-in fits; its plans are built in `compact` mode and every round and message is
//! compared.
//!
//! The one deliberate deviation is the `OneList` counter: the C++ headers keep it in a static;
//! the port passes a fresh counter into each file construction. It numbers trees only, which no
//! line prints.

use fp_core::frame::derive::{derive, Derived, FrameShape, TestSizes};
use fp_core::frame::files::{
    file_entry, file_key, file_proof, merged, sized, stand_in_subproofs, Sized, Subproofs,
};
use fp_core::frame::heads::parameter_file_digest;
use fp_core::frame::key_fixed::{key_fault, key_fixed, key_public_bytes, KeyFixed};
use fp_core::frame::lin_frame::LinSized;
use fp_core::frame::link_frame::LinkSized;
use fp_core::frame::parameters::{read_parameters, Parameters};
use fp_core::frame::wf_frame::WfSized;
use fp_core::hash::calls::HashCalls;
use fp_core::hash::modes::Digest;
use fp_core::iop::foldeq::IndexShape;
use fp_core::iop::relation::{Codes, OracleShape};
use fp_core::iop::wf::WfPublic;
use fp_core::numbers::blocks::{GroupSize, TableSize};
use fp_core::numbers::plan::{MessageKind, PlanMessage, PlanRound, Planned, Priced, TableTest};
use fp_core::numbers::real::{Big, Real};

const POLICY: &str = include_str!("../../fixtures/config/policy.txt");
const FIT: &str = include_str!("../../fixtures/config-standin/policy.txt");
const VECTORS: &str = include_str!("../../fixtures/frame_files_vectors.txt");

// ---------------------------------------------------------------------------------------------------------------------
// The C++ tool's line format

fn hex(s: &str) -> String {
    s.as_bytes().iter().map(|b| format!("{b:02x}")).collect()
}

fn hex_or_dash(s: &str) -> String {
    if s.is_empty() {
        String::from("-")
    } else {
        hex(s)
    }
}

fn bytes_hex(v: &[u8]) -> String {
    v.iter().map(|b| format!("{b:02x}")).collect()
}

fn digest_hex(d: &Digest) -> String {
    bytes_hex(&d.to_bytes())
}

fn group_str(g: &GroupSize) -> String {
    format!(
        "name={} main={},{},{},{} mask={},{},{},{} k={} h={} slots={} rule={} m={}",
        hex(&g.name),
        g.main.log_n,
        g.main.ell,
        g.main.r,
        g.main.over_e as u8,
        g.mask.log_n,
        g.mask.ell,
        g.mask.r,
        g.mask.over_e as u8,
        g.k,
        g.h,
        g.slots,
        g.rule as u8,
        g.m
    )
}

fn shape_str(o: &OracleShape) -> String {
    format!(
        "name={} code={} main_rows={} main_deg={} mask_rows={} mask_code={} answers={}",
        hex(&o.name),
        o.code,
        o.main_rows,
        o.main_deg,
        o.mask_rows,
        o.mask_code,
        o.answers
    )
}

fn index_str(s: &IndexShape) -> String {
    format!(
        "log_n={} ell={} r={} v={} answers={} salt={} radius={} later={} m_once={} m_later={}",
        s.code.log_n,
        s.code.ell,
        s.code.r,
        s.v,
        s.answers,
        s.salt_bytes,
        s.distances.radius,
        s.distances.later_radius,
        s.distances.m_once,
        s.distances.m_later
    )
}

fn table_str(t: &TableSize) -> String {
    format!(
        "log_n={} ell={} r={} v={} answers={} radius={} later={} m_once={} m_later={}",
        t.code.log_n,
        t.code.ell,
        t.code.r,
        t.v,
        t.answers,
        t.distances.radius,
        t.distances.later_radius,
        t.distances.m_once,
        t.distances.m_later
    )
}

fn push_test(out: &mut String, name: &str, test: &str, x: &TestSizes) {
    out.push_str(&format!(
        "LTEST name={} test={} t={} group={} stages={}\n",
        name,
        test,
        x.t,
        group_str(&x.group),
        x.stages.len()
    ));
    for (i, s) in x.stages.iter().enumerate() {
        out.push_str(&format!(
            "LSTAGE name={} test={} i={} t={} r_ood={} group={}\n",
            name,
            test,
            i,
            s.t,
            s.r_ood,
            group_str(&s.g)
        ));
    }
}

fn push_codes(out: &mut String, name: &str, codes: &Codes) {
    out.push_str(&format!(
        "LCODES name={} base={} mask={}\n",
        name,
        codes.base.len(),
        codes.mask.len()
    ));
    for (i, c) in codes.base.iter().enumerate() {
        out.push_str(&format!(
            "LCODE name={} kind=base i={} log_n={} ell={} r={}\n",
            name, i, c.log_n, c.ell, c.r
        ));
    }
    for (i, c) in codes.mask.iter().enumerate() {
        out.push_str(&format!(
            "LCODE name={} kind=mask i={} log_n={} ell={} r={}\n",
            name, i, c.log_n, c.ell, c.r
        ));
    }
}

fn push_lin_members(out: &mut String, name: &str, s: &fp_core::iop::lin::LinShape) {
    out.push_str(&format!("LINDEX name={} {}\n", name, index_str(&s.fold.index)));
    out.push_str(&format!(
        "LSHAPE name={} at=fold.u {} leaf={}\n",
        name,
        shape_str(&s.fold.u),
        s.fold.leaf_class
    ));
    out.push_str(&format!("LSHAPE name={} at=omega {}\n", name, shape_str(&s.omega)));
    out.push_str(&format!("LSHAPE name={} at=w {}\n", name, shape_str(&s.w)));
    out.push_str(&format!(
        "LSHAPE name={} at=shared_split {}\n",
        name,
        shape_str(&s.shared_split)
    ));
    out.push_str(&format!("LSHAPE name={} at=own_split {}\n", name, shape_str(&s.own_split)));
    for (label, stages) in [
        ("u", &s.test_u),
        ("omega", &s.test_omega),
        ("own", &s.test_own),
        ("own_omega", &s.test_own_omega),
    ] {
        out.push_str(&format!("LSTAGES name={} test={} n={}\n", name, label, stages.len()));
        for (i, st) in stages.iter().enumerate() {
            out.push_str(&format!(
                "LIOPP name={} test={} i={} code={} mask_code={} k={} h={}\n",
                name, label, i, st.code, st.mask_code, st.k, st.h
            ));
        }
    }
}

fn push_lin(out: &mut String, name: &str, x: &LinSized, codes: &Codes) {
    let s = &x.s;
    out.push_str(&format!(
        "LIN name={} refused={} k_lo={} matrix_rows={} omega_rh={} w_rh={} masks_ahead={} ride={} shared_mask={} own_mask={} batches={} shared_split={} own_split={} columns={} fold_rh={} omega_lc={} split_lc={} w_lc={} own_lc={}\n",
        name,
        hex_or_dash(&x.refused),
        s.k_lo,
        s.matrix_rows,
        s.omega_rows_high as u8,
        s.w_rows_high as u8,
        s.masks_ahead as u8,
        s.choice.masks_ride as u8,
        s.shared_mask_code,
        s.own_mask_code,
        x.batches,
        s.shared_split_needed() as u8,
        s.own_split_needed() as u8,
        s.fold.columns,
        s.fold.rows_high as u8,
        s.omega_leaf_class,
        s.shared_split_leaf_class,
        s.w_leaf_class,
        s.own_split_leaf_class
    ));
    push_lin_members(out, name, s);
    out.push_str(&format!(
        "LINPUT name={} {} leaf={}\n",
        name,
        shape_str(&x.input.shape),
        x.input.leaf_class
    ));
    push_test(out, name, "folded", &x.folded);
    push_test(out, name, "omega", &x.omega);
    push_test(out, name, "own", &x.own);
    out.push_str(&format!("LTABLE name={} {}\n", name, table_str(&x.table)));
    push_codes(out, name, codes);
}

fn push_link(out: &mut String, name: &str, x: &LinkSized, codes: &Codes) {
    let s = &x.s;
    out.push_str(&format!(
        "LINK name={} refused={} columns_first={} columns_further={} code={} mask_code={} rows={} rows_high={} leaf_class={} masks_ahead={} ride={} later={}\n",
        name,
        hex_or_dash(&x.refused),
        s.columns_first,
        s.columns_further,
        s.code,
        s.mask_code,
        s.rows,
        s.rows_high as u8,
        s.leaf_class,
        s.masks_ahead as u8,
        s.choice.masks_ride as u8,
        s.later.len()
    ));
    out.push_str(&format!("LINDEX name={} {}\n", name, index_str(&s.table)));
    for (i, st) in s.later.iter().enumerate() {
        out.push_str(&format!(
            "LLATER name={} i={} code={} mask_code={} k={} h={}\n",
            name, i, st.code, st.mask_code, st.k, st.h
        ));
    }
    push_test(out, name, "linked", &x.linked);
    out.push_str(&format!("LTABLE name={} {}\n", name, table_str(&x.table)));
    push_codes(out, name, codes);
}

fn push_wf_public(out: &mut String, name: &str, x: &WfPublic) {
    for (i, l) in x.lookups.iter().enumerate() {
        let weights: Vec<String> = l.digit_weight.iter().map(|w| w.0.to_string()).collect();
        let bounds: Vec<String> = l.first_bound.iter().map(|b| b.to_string()).collect();
        let weights = if weights.is_empty() { String::from("-") } else { weights.join(",") };
        let bounds = if bounds.is_empty() { String::from("-") } else { bounds.join(",") };
        out.push_str(&format!(
            "WLOOKUP name={} i={} name_hex={} d={} mu={} live={} weights={} offset={} pad={} first_bound={} parts={}\n",
            name,
            i,
            hex(&l.name),
            l.d,
            l.mu,
            l.live,
            weights,
            l.offset.0,
            l.padding_key.0,
            bounds,
            l.parts.len()
        ));
        for (j, p) in l.parts.iter().enumerate() {
            out.push_str(&format!(
                "WPART name={} i={} j={} log_places={} runs={}\n",
                name,
                i,
                j,
                p.log_places,
                p.runs.len()
            ));
            for (k, r) in p.runs.iter().enumerate() {
                out.push_str(&format!(
                    "WRUN name={} i={} j={} k={} first_place={} first_row={} places={} stride={}\n",
                    name, i, j, k, r.first_place, r.first_row, r.places, r.stride
                ));
            }
        }
    }
    out.push_str(&format!(
        "WSHAPE name={} {} leaf={}\n",
        name,
        shape_str(&x.message.shape),
        x.message.leaf_class
    ));
    out.push_str(&format!("WSTAGES name={} n={}\n", name, x.stages.len()));
    for (i, st) in x.stages.iter().enumerate() {
        out.push_str(&format!(
            "WIOPP name={} i={} code={} mask_code={} k={} h={}\n",
            name, i, st.code, st.mask_code, st.k, st.h
        ));
    }
    out.push_str(&format!("WCHOICE name={} ride={}\n", name, x.choice.masks_ride as u8));
}

fn push_wf(out: &mut String, name: &str, z: &WfSized, codes: &Codes) {
    let x = &z.x;
    out.push_str(&format!(
        "WF name={} refused={} k_col={} rows={} pending={} message_id={} ride={} own_masks={} rows_batched={} index_mask_entries={}\n",
        name,
        hex_or_dash(&z.refused),
        z.matrix.k_col,
        z.matrix.rows,
        z.pending,
        x.message_id,
        x.choice.masks_ride as u8,
        fp_core::iop::wf::wf_own_masks(x, &z.matrix),
        fp_core::iop::wf::wf_rows_batched(x, &z.matrix),
        fp_core::iop::wf::wf_index_mask_entries(x, &z.matrix)
    ));
    push_wf_public(out, name, x);
    push_test(out, name, "test", &z.test);
    push_codes(out, name, codes);
}

fn push_request(out: &mut String, name: &str, s: &fp_core::iop::req::ReqShape) {
    out.push_str(&format!(
        "REQUEST name={} code={} mask_code={} answers={} links={} at_start={} last={} ride={}\n",
        name,
        s.code,
        s.mask_code,
        s.answers,
        s.link.len(),
        s.at_start.len(),
        s.last.len(),
        s.choice.masks_ride as u8
    ));
    for (i, n) in s.at_start.iter().enumerate() {
        out.push_str(&format!(
            "QSTART name={} i={} {} leaf={}\n",
            name,
            i,
            shape_str(&n.shape),
            n.leaf_class
        ));
    }
    for (i, l) in s.link.iter().enumerate() {
        out.push_str(&format!(
            "QLINK name={} i={} name_hex={} plain={} messages={}\n",
            name,
            i,
            hex(&l.name),
            l.plain,
            l.messages.len()
        ));
        for (j, m) in l.messages.iter().enumerate() {
            out.push_str(&format!(
                "QMSG name={} i={} j={} name_hex={} code={} main_rows={} main_deg={} mask_rows={} mask_code={} answers={} leaf={} moment={} life={}\n",
                name,
                i,
                j,
                hex(&m.shape.name),
                m.shape.code,
                m.shape.main_rows,
                m.shape.main_deg,
                m.shape.mask_rows,
                m.shape.mask_code,
                m.shape.answers,
                m.leaf_class,
                m.moment,
                m.life
            ));
        }
    }
    for (i, st) in s.last.iter().enumerate() {
        out.push_str(&format!(
            "QLAST name={} i={} code={} mask_code={} k={} h={}\n",
            name, i, st.code, st.mask_code, st.k, st.h
        ));
    }
}

fn push_subproofs(out: &mut String, name: &str, sub: &Subproofs) {
    push_request(out, &format!("{}/request", name), &sub.request);
    let rows: Vec<String> = sub.open_rows.iter().map(|r| r.to_string()).collect();
    out.push_str(&format!(
        "SUB name={} open_rows={} open_rows_list={} pending={} ranges_k_col={} ranges_rows={} ranges_lookups={}\n",
        name,
        sub.open_rows.len(),
        rows.join(","),
        sub.pending_rows,
        sub.ranges.k_col,
        sub.ranges.matrix_rows,
        sub.ranges.lookups.len()
    ));
    for (i, l) in sub.ranges.lookups.iter().enumerate() {
        let weights: Vec<String> =
            l.lookup.digit_weight.iter().map(|w| w.0.to_string()).collect();
        let bounds: Vec<String> = l.lookup.first_bound.iter().map(|b| b.to_string()).collect();
        let weights = if weights.is_empty() { String::from("-") } else { weights.join(",") };
        let bounds = if bounds.is_empty() { String::from("-") } else { bounds.join(",") };
        out.push_str(&format!(
            "SUBL name={} i={} name_hex={} d={} weights={} offset={} first_bound={} log_rows_apart={} entries={}\n",
            name,
            i,
            hex(&l.lookup.name),
            l.lookup.d,
            weights,
            l.lookup.offset.0,
            bounds,
            l.log_rows_apart,
            l.entries.len()
        ));
        for (j, r) in l.entries.iter().enumerate() {
            out.push_str(&format!(
                "SUBRUN name={} i={} j={} first_place={} first_row={} places={} stride={}\n",
                name, i, j, r.first_place, r.first_row, r.places, r.stride
            ));
        }
    }
}

fn push_sized(out: &mut String, name: &str, z: &Sized) {
    out.push_str(&format!("SIZED name={} refused={}\n", name, hex_or_dash(&z.refused)));
    push_request(out, &format!("{}/request", name), &z.request);
    out.push_str(&format!(
        "SDERIVED name={} refused={} table={}\n",
        name,
        hex_or_dash(&z.d.refused),
        table_str(&z.d.table)
    ));
    push_test(out, name, "link", &z.d.link);
    push_test(out, name, "last", &z.d.last);
    push_lin(out, &format!("{}/batch", name), &z.batch, &z.proof_codes);
    push_lin(out, &format!("{}/once", name), &z.once, &z.key_codes);
    push_wf(out, &format!("{}/ranges", name), &z.ranges, &z.key_codes);
    push_link(out, &format!("{}/link", name), &z.link, &z.entry_codes);
    push_codes(out, &format!("{}/proof_codes", name), &z.proof_codes);
    push_codes(out, &format!("{}/key_codes", name), &z.key_codes);
    push_codes(out, &format!("{}/entry_codes", name), &z.entry_codes);
}

fn big_hex(b: &Big) -> String {
    if b.is_zero() {
        return String::from("0");
    }
    b.w.iter().map(|w| format!("{:08x}", w)).collect::<Vec<_>>().join(",")
}

fn real_str(r: &Real) -> String {
    format!("{}@{}", big_hex(&r.m), r.e)
}

fn priced_int(p: Priced) -> u32 {
    match p {
        Priced::Nothing => 0,
        Priced::SettingAlone => 1,
        Priced::TheRoundItself => 2,
        Priced::AsSaid => 3,
        Priced::OnTheCallersWord => 4,
    }
}

fn table_test_int(t: TableTest) -> u32 {
    match t {
        TableTest::Later => 0,
        TableTest::OneTime => 1,
        TableTest::Link => 2,
    }
}

fn message_kind_int(k: MessageKind) -> u32 {
    match k {
        MessageKind::Scalars => 0,
        MessageKind::Answers => 1,
        MessageKind::Root => 2,
        MessageKind::Nonce => 3,
        MessageKind::Columns => 4,
        MessageKind::Salts => 5,
        MessageKind::Paths => 6,
        MessageKind::Head => 7,
    }
}

fn round_line(i: usize, r: &PlanRound) -> String {
    format!(
        "ROUND\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\t{}\n",
        i,
        hex(&r.name),
        hex(&r.where_),
        r.kind as u32,
        r.why as usize,
        r.scope as usize,
        real_str(&r.error),
        r.rests as u32,
        r.work_bits,
        r.count,
        r.part,
        r.message_bytes,
        r.roots,
        r.answers,
        r.draw_e,
        r.draw_nonzero,
        r.draw_positions,
        r.log_n,
        r.draw_trits,
        r.rows,
        r.first_list,
        r.combinations,
        r.sharing,
        priced_int(r.priced),
        r.group.said as u8,
        r.group.main.log_n,
        r.group.main.ell,
        r.group.main.r,
        r.group.mask.log_n,
        r.group.mask.ell,
        r.group.mask.r,
        r.group.k,
        r.group.h,
        r.group.slots,
        r.group.rule,
        r.group.m,
        r.table.said as u8,
        r.table.code.log_n,
        r.table.code.ell,
        r.table.code.r,
        r.table.v,
        r.table.answers,
        r.table.distances.radius,
        r.table.distances.later_radius,
        r.table.distances.m_once,
        r.table.distances.m_later,
        table_test_int(r.table.test)
    )
}

fn msg_line(i: usize, m: &PlanMessage) -> String {
    format!(
        "MSG\t{}\t{}\t{}\t{}\t{}\t{:x}\t{}\t{}\t{}\t{}\n",
        i,
        hex(&m.name),
        hex(&m.where_),
        message_kind_int(m.kind),
        m.bytes,
        m.expected.to_bits(),
        m.count,
        m.part,
        m.in_chain as u8,
        m.hash_calls
    )
}

fn push_planned(out: &mut String, name: &str, q: &Planned) {
    out.push_str(&format!("PLAN name={}\n", name));
    out.push_str(&format!("VERDICT {} {}\n", q.cause() as u32, hex_or_dash(q.why_not())));
    out.push_str(&format!("QUERIES {}\n", q.queries()));
    for (i, part) in q.parts.iter().enumerate() {
        out.push_str(&format!("PART {} {}\n", i, hex(part)));
    }
    for i in 0..q.parts.len() {
        let (bytes, expected) = q.size_of(i as u32);
        out.push_str(&format!("PSIZE {} {} {:x}\n", i, bytes, expected.to_bits()));
    }
    for (i, r) in q.rounds.iter().enumerate() {
        out.push_str(&round_line(i, r));
    }
    for (i, m) in q.messages.iter().enumerate() {
        out.push_str(&msg_line(i, m));
    }
}

fn push_file(out: &mut String, label: &str, f: &fp_core::frame::files::FilePlan) {
    out.push_str(&format!(
        "FILE label={} name={} head_words={} place_depth={} has_place={} chains={}\n",
        label,
        hex(&f.name),
        f.head_words,
        f.place_depth,
        f.has_place as u8,
        f.chains.len()
    ));
    for (i, c) in f.chains.iter().enumerate() {
        out.push_str(&format!(
            "CHAIN label={} file={} i={} name_hex={}\n",
            label,
            hex(&f.name),
            i,
            hex(&c.name)
        ));
        push_planned(out, &format!("{}/{}/{}", label, f.name, c.name), &c.plan);
    }
}

fn push_key(out: &mut String, name: &str, f: &KeyFixed) {
    out.push_str(&format!(
        "KEY name={} configuration={} binding_log_leaves={} binding_salt_bytes={}\n",
        name,
        digest_hex(&f.configuration),
        f.binding.log_leaves,
        f.binding.salt_bytes
    ));
    push_codes(out, &format!("{}/codes", name), &f.codes);
    let s = &f.lin;
    out.push_str(&format!(
        "KEYLIN name={} k_lo={} matrix_rows={} omega_rh={} w_rh={} masks_ahead={} ride={} shared_mask={} own_mask={} shared_split={} own_split={} columns={} fold_rh={} omega_lc={} split_lc={} w_lc={} own_lc={}\n",
        name,
        s.k_lo,
        s.matrix_rows,
        s.omega_rows_high as u8,
        s.w_rows_high as u8,
        s.masks_ahead as u8,
        s.choice.masks_ride as u8,
        s.shared_mask_code,
        s.own_mask_code,
        s.shared_split_needed() as u8,
        s.own_split_needed() as u8,
        s.fold.columns,
        s.fold.rows_high as u8,
        s.omega_leaf_class,
        s.shared_split_leaf_class,
        s.w_leaf_class,
        s.own_split_leaf_class
    ));
    push_lin_members(out, &format!("{}/lin", name), s);
    out.push_str(&format!(
        "KEYMASKS name={} {} leaf={}\n",
        name,
        shape_str(&f.index_masks.shape),
        f.index_masks.leaf_class
    ));
    push_wf_public(out, &format!("{}/ranges", name), &f.ranges);
    let bytes = key_public_bytes(f);
    out.push_str(&format!("KEYBYTES name={} n={} {}\n", name, bytes.len(), bytes_hex(&bytes)));
    out.push_str(&format!(
        "KEYFAULT name={} {}\n",
        name,
        key_fault(f).map(hex).unwrap_or_else(|| String::from("-"))
    ));
}

// ---------------------------------------------------------------------------------------------------------------------
// One whole flow, as the C++ tool's run()

fn run(out: &mut String, label: &str, par: &Parameters, text: &[u8], compact: bool) {
    let d: Derived = derive(par, &FrameShape::default());
    out.push_str(&format!(
        "DERIVED name={} refused={} table={}\n",
        label,
        hex_or_dash(&d.refused),
        table_str(&d.table)
    ));
    push_test(out, label, "link", &d.link);
    push_test(out, label, "last", &d.last);

    let sub = stand_in_subproofs();
    push_subproofs(out, &format!("{}/stand_in", label), &sub);

    let z = sized(par, &sub);
    push_sized(out, &format!("{}/sized", label), &z);

    let mut last = 0u64;
    let proof = file_proof(&z, &sub, compact, &mut last);
    let mut last = 0u64;
    let key = file_key(&z, compact, &mut last);
    let mut last = 0u64;
    let entry = file_entry(&z, compact, &mut last);
    push_file(out, &format!("{}/sized", label), &proof);
    push_file(out, &format!("{}/sized", label), &key);
    push_file(out, &format!("{}/sized", label), &entry);
    let whole = merged(&z.d.set, &[proof, key, entry]);
    push_planned(out, &format!("{}/sized/merged", label), &whole);

    let mut calls = HashCalls::default();
    let configuration = parameter_file_digest(text, &mut calls);
    let fixed = key_fixed(&z, &configuration);
    push_key(out, &format!("{}/key", label), &fixed);
    push_key_fault_cases(out, &format!("{}/key", label), &fixed);
}

/// The later checks of `key_fault`: one field broken at a time on a key that otherwise passes.
fn push_key_fault_cases(out: &mut String, name: &str, base: &KeyFixed) {
    fn show(out: &mut String, name: &str, what: &str, f: &KeyFixed) {
        out.push_str(&format!(
            "KEYFAULT2 name={} case={} fault={}\n",
            name,
            what,
            key_fault(f).map(hex).unwrap_or_else(|| String::from("-"))
        ));
    }
    show(out, name, "base", base);
    {
        let mut f = base.clone();
        f.lin.matrix_rows = 0;
        show(out, name, "lin", &f);
    }
    {
        let mut f = base.clone();
        f.ranges.lookups.clear();
        show(out, name, "ranges", &f);
    }
    {
        let mut f = base.clone();
        f.binding.log_leaves = 1;
        show(out, name, "binding", &f);
    }
    {
        let mut f = base.clone();
        f.ranges.message_id = 0;
        show(out, name, "message_id", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.main_rows = 1;
        show(out, name, "mask_main_rows", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.mask_rows = 0;
        show(out, name, "mask_no_rows", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.answers = 0;
        show(out, name, "mask_no_answers", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.mask_code = f.codes.mask.len() as u32;
        show(out, name, "mask_code", &f);
    }
    {
        let mut f = base.clone();
        f.index_masks.shape.mask_rows = 1;
        // A base whose codes are empty (a refused key) still gives a deterministic case.
        let code = f.index_masks.shape.mask_code as usize;
        let ell = if f.codes.mask.is_empty() {
            1
        } else {
            f.codes.mask[if code < f.codes.mask.len() { code } else { 0 }].ell as u32
        };
        f.index_masks.shape.answers = ell;
        show(out, name, "mask_no_room", &f);
    }
}

fn parse(text: &[u8], name: &str, out: &mut String) -> Option<Parameters> {
    let mut p = Parameters::default();
    match read_parameters(text, &mut p) {
        Ok(()) => {
            out.push_str(&format!("PARAMS name={} read=1\n", name));
            Some(p)
        }
        Err(why) => {
            out.push_str(&format!("PARAMS name={} read=0 why={}\n", name, hex(&why)));
            None
        }
    }
}

#[test]
fn frame_files_match_the_cpp_reference() {
    let mut out = String::new();
    if let Some(p) = parse(POLICY.as_bytes(), "policy", &mut out) {
        run(&mut out, "policy", &p, POLICY.as_bytes(), false);
    }
    if let Some(p) = parse(FIT.as_bytes(), "fit", &mut out) {
        run(&mut out, "fit", &p, FIT.as_bytes(), true);
    }

    let got: Vec<&str> = out.lines().collect();
    let want: Vec<&str> = VECTORS.lines().collect();
    for i in 0..got.len().min(want.len()) {
        if !same_line(got[i], want[i]) {
            let a = got[i];
            let b = want[i];
            panic!(
                "line {} differs\n  rust: {}\n  cpp:  {}",
                i + 1,
                if a.len() > 400 { &a[..400] } else { a },
                if b.len() > 400 { &b[..400] } else { b }
            );
        }
    }
    assert_eq!(got.len(), want.len(), "the number of lines");
}

/// MSG field 6 and PSIZE field 2 are averages computed through libm: the C++ and Rust libraries
/// may differ in the last bits, as in the plan-emitter vectors. Everything else is exact.
fn same_line(got: &str, want: &str) -> bool {
    if got == want {
        return true;
    }
    let g: Vec<&str> = got.split('\t').collect();
    let w: Vec<&str> = want.split('\t').collect();
    if g.len() > 1 && g.first() == Some(&"MSG") {
        if g.len() != w.len() {
            return false;
        }
        for i in 0..g.len() {
            if i != 6 && g[i] != w[i] {
                return false;
            }
        }
        return close_float(g[6], w[6]);
    }
    let gp: Vec<&str> = got.split(' ').collect();
    let wp: Vec<&str> = want.split(' ').collect();
    if gp.len() != wp.len() || gp.first() != Some(&"PSIZE") {
        return false;
    }
    for i in 0..gp.len() {
        if i != 3 && gp[i] != wp[i] {
            return false;
        }
    }
    close_float(gp[3], wp[3])
}

fn close_float(a: &str, b: &str) -> bool {
    let x = f64::from_bits(u64::from_str_radix(a, 16).unwrap());
    let y = f64::from_bits(u64::from_str_radix(b, 16).unwrap());
    let tol = 1e-9 * x.abs().max(y.abs()).max(1.0);
    (x - y).abs() <= tol
}
